import numpy as np

def loss(w1, w2):
    return 0.5 * (w1**2 + 1.8 * w2**2)

def gradient_descent(lr=0.1, steps=16):
    w1, w2 = 2.6, -2.2
    history = []
    for t in range(steps + 1):
        history.append((t, round(w1, 4), round(w2, 4), round(loss(w1, w2), 4)))
        dw1, dw2 = w1, 1.8 * w2
        w1 -= lr * dw1
        w2 -= lr * dw2
    return history

for row in gradient_descent(lr=0.1, steps=10):
    print(row)
